{"command":"cat <<'EOF' > test_json_ordered.go
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
)

type MapSlice []MapItem
type MapItem struct {
	Key   interface{}
	Value interface{}
}

func decodeJSON(d *json.Decoder) (interface{}, error) {
	t, err := d.Token()
	if err != nil {
		return nil, err
	}
	switch v := t.(type) {
	case json.Delim:
		if v == '{' {
			var slice MapSlice
			for d.More() {
				k, err := d.Token()
				if err != nil {
					return nil, err
				}
				val, err := decodeJSON(d)
				if err != nil {
					return nil, err
				}
				slice = append(slice, MapItem{Key: k, Value: val})
			}
			_, err := d.Token() // read '}'
			return slice, err
		} else if v == '[' {
			var arr []interface{}
			for d.More() {
				val, err := decodeJSON(d)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			_, err := d.Token() // read ']'
			return arr, err
		}
		return nil, fmt.Errorf("unexpected delim %v", v)
	default:
		return v, nil
	}
}

func main() {
	d := json.NewDecoder(bytes.NewReader([]byte(`{"z": 1, "a": {"c": 2}}`)))
	val, err := decodeJSON(d)
	fmt.Printf("%#v %v\n", val, err)
}
EOF
go run test_json_ordered.go"}

