{"command":"cat <<'EOF' > test_json_encode.go
package main

import (
	"bytes"
	"fmt"
)

type MapItem struct {
	Key   interface{}
	Value interface{}
}
type MapSlice []MapItem

func encodeJSON(val interface{}, escapeHTML bool) ([]byte, error) {
	var buf bytes.Buffer
	err := encodeJSONValue(val, &buf, escapeHTML)
	return buf.Bytes(), err
}

func encodeJSONValue(val interface{}, buf *bytes.Buffer, escapeHTML bool) error {
	switch v := val.(type) {
	case MapSlice:
		buf.WriteByte('{')
		for i, item := range v {
			if i > 0 {
				buf.WriteByte(',')
			}
			// Encode key
			k, _ := encodeJSON(item.Key, escapeHTML)
			buf.Write(k)
			buf.WriteByte(':')
			err := encodeJSONValue(item.Value, buf, escapeHTML)
			if err != nil {
				return err
			}
		}
		buf.WriteByte('}')
	case []interface{}:
		buf.WriteByte('[')
		for i, item := range v {
			if i > 0 {
				buf.WriteByte(',')
			}
			err := encodeJSONValue(item, buf, escapeHTML)
			if err != nil {
				return err
			}
		}
		buf.WriteByte(']')
	default:
		// use standard json
		// ...
		buf.WriteString(fmt.Sprintf("%v", v))
	}
	return nil
}

func main() {
	slice := MapSlice{
		{Key: "a", Value: 1},
		{Key: "b", Value: 2},
	}
	b, _ := encodeJSON(slice, false)
	fmt.Printf("%s\n", b)
}
EOF
go run test_json_encode.go"}

