func decodeJSON(d *json.Decoder) (interface{}, error) {
	t, err := d.Token()
	if err != nil {
		return nil, err
	}
	switch v := t.(type) {
	case json.Delim:
		if v == '{' {
			var slice yaml.MapSlice
			for d.More() {
				k, err := d.Token()
				if err != nil {
					return nil, err
				}
				val, err := decodeJSON(d)
				if err != nil {
					return nil, err
				}
				slice = append(slice, yaml.MapItem{Key: k, Value: val})
			}
			_, err := d.Token()
			return slice, err
		} else if v == '[' {
			var arr []interface{}
			for d.More() {
				val, err := decodeJSON(d)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			_, err := d.Token()
			return arr, err
		}
		return nil, fmt.Errorf("unexpected delim %v", v)
	default:
		return v, nil
	}
