				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			_, err := d.Token()
			return arr, err
		}
		return nil, fmt.Errorf("unexpected delim %v", v)
	default:
		return v, nil
	}
}

func encodeJSON(val interface{}, escapeHTML bool, indent bool) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(escapeHTML)
	if indent {
		enc.SetIndent("", "  ")
	}
	err := encodeJSONValue(val, enc, &buf, escapeHTML, indent, 0)
	return buf.Bytes(), err
}

func encodeJSONValue(val interface{}, enc *json.Encoder, buf *bytes.Buffer, escapeHTML, indent bool, depth int) error {
	switch v := val.(type) {
	case yaml.MapSlice:
		buf.WriteByte('{')
		if indent && len(v) > 0 {
			buf.WriteByte('\n')
		}
		for i, item := range v {
			if i > 0 {
				buf.WriteByte(',')
				if indent {
					buf.WriteByte('\n')
				}
			}
			if indent {
				buf.WriteString(strings.Repeat("  ", depth+1))
			}
			kBytes, _ := json.Marshal(fmt.Sprintf("%v", item.Key))
			buf.Write(kBytes)
			buf.WriteByte(':')
			if indent {
				buf.WriteByte(' ')
			}
			err := encodeJSONValue(item.Value, enc, buf, escapeHTML, indent, depth+1)
			if err != nil {
				return err
			}
		}
		if indent && len(v) > 0 {
			buf.WriteByte('\n')
			buf.WriteString(strings.Repeat("  ", depth))
		}
		buf.WriteByte('}')
	case []interface{}:
		buf.WriteByte('[')
		if indent && len(v) > 0 {
			buf.WriteByte('\n')
		}
		for i, item := range v {
			if i > 0 {
				buf.WriteByte(',')
				if indent {
					buf.WriteByte('\n')
				}
			}
			if indent {
				buf.WriteString(strings.Repeat("  ", depth+1))
			}
			err := encodeJSONValue(item, enc, buf, escapeHTML, indent, depth+1)
			if err != nil {
				return err
			}
		}
		if indent && len(v) > 0 {
			buf.WriteByte('\n')
			buf.WriteString(strings.Repeat("  ", depth))
		}
		buf.WriteByte(']')
	default:
		b, err := json.Marshal(v)
		if err != nil {
			return err
		}
		if escapeHTML {
			b = bytes.ReplaceAll(b, []byte("<"), []byte("\\u003c"))
			b = bytes.ReplaceAll(b, []byte(">"), []byte("\\u003e"))
			b = bytes.ReplaceAll(b, []byte("&"), []byte("\\u0026"))
		}
		buf.Write(b)
	}
	return nil
}

func sanitizeFloats(v interface{}, keepFloats bool) interface{} {
	switch val := v.(type) {
	case float64:
		if math.IsNaN(val) {
			if keepFloats {
				return nil
			}
			return "NaN"
		} else if math.IsInf(val, 1) {
			if keepFloats {
				return math.MaxFloat64
			}
			return "Infinity"
		} else if math.IsInf(val, -1) {
			if keepFloats {
				return -math.MaxFloat64
			}
			return "-Infinity"
		}
		return val
	case yaml.MapSlice:
		var s yaml.MapSlice
		for _, item := range val {
			s = append(s, yaml.MapItem{Key: item.Key, Value: sanitizeFloats(item.Value, keepFloats)})
		}
		return s
	case []interface{}:
		var a []interface{}
		for _, item := range val {
			a = append(a, sanitizeFloats(item, keepFloats))
		}
		return a
	case map[string]interface{}:
		m := make(map[string]interface{})
		for k, vv := range val {
			m[k] = sanitizeFloats(vv, keepFloats)
		}
		return m
	}
	return v
}

func parseFloats(v interface{}, keepFloats bool) interface{} {
	if keepFloats {
		return v
	}
	switch val := v.(type) {
	case string:
		if val == "Infinity" || val == "+inf" {
			return math.Inf(1)
		}
		if val == "-Infinity" || val == "-inf" {
			return math.Inf(-1)
		}
		if val == "NaN" || val == "nan" {
			return math.NaN()
		}
	case yaml.MapSlice:
		var s yaml.MapSlice
		for _, item := range val {
			s = append(s, yaml.MapItem{Key: item.Key, Value: parseFloats(item.Value, keepFloats)})
		}
		return s
	case []interface{}:
		var a []interface{}
		for _, item := range val {
			a = append(a, parseFloats(item, keepFloats))
		}
		return a
	case map[string]interface{}:
		m := make(map[string]interface{})
		for k, vv := range val {
			m[k] = parseFloats(vv, keepFloats)
		}
		return m
	}
	return v
}

func astToSlice(node interface{}) interface{} {
	val := reflect.ValueOf(node)
	if val.Kind() == reflect.Ptr {
		if val.IsNil() {
			return nil
		}
		val = val.Elem()
	}
	typ := val.Type().Name()
	switch typ {
	case "File":
		return astToSlice(val.FieldByName("Node").Interface())
	case "ObjectList":
		items := val.FieldByName("Items")
		var slice yaml.MapSlice
		for i := 0; i < items.Len(); i++ {
			item := items.Index(i).Elem()
			keys := item.FieldByName("Keys")
			if keys.Len() > 0 {
				keyTok := keys.Index(0).Elem().FieldByName("Token").FieldByName("Text").String()
				key := strings.Trim(keyTok, `"`)
				v := astToSlice(item.FieldByName("Val").Interface())
				slice = append(slice, yaml.MapItem{Key: key, Value: v})
			}
		}
		return slice
	case "ObjectType":
		return astToSlice(val.FieldByName("List").Interface())
	case "ListType":
		lst := val.FieldByName("List")
		var arr []interface{}
		for i := 0; i < lst.Len(); i++ {
			arr = append(arr, astToSlice(lst.Index(i).Interface()))
		}
		return arr
	case "LiteralType":
		tok := val.FieldByName("Token")
		text := tok.FieldByName("Text").String()
		if text == "true" {
			return true
		}
		if text == "false" {
			return false
		}
		if text == "null" {
			return nil
		}
		if strings.HasPrefix(text, `"`) {
			return strings.Trim(text, `"`)
		}
		var n float64
		if _, err := fmt.Sscanf(text, "%f", &n); err == nil {
			return n
		}
		return text
	}
	return nil
}

func main() {
	var inFormat, outFormat string
	var keepFloats, escapeHTML, indent, parseKeys bool
	args := os.Args[1:]

	inFormat = "y"
	outFormat = "j"

	for _, arg := range args {
		if arg == "-h" {
			fmt.Println(`Usage: yj [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version`)
			return
		}
		if arg == "-v" {
			fmt.Println("v0.0.0")
			return
		}
		if arg == "-n" {
			keepFloats = true
		} else if arg == "-e" {
			escapeHTML = true
		} else if arg == "-i" {
			indent = true
		} else if arg == "-k" {
			parseKeys = true
		} else if strings.HasPrefix(arg, "-") && len(arg) == 2 {
			inFormat = string(arg[1])
			if inFormat == "r" {
				inFormat = "j"
				outFormat = "y"
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) == 3 {
			inFormat = string(arg[1])
			outFormat = string(arg[2])
		}
	}

	inputBytes, err := ioutil.ReadAll(os.Stdin)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading stdin: %v\n", err)
		os.Exit(1)
	}

	var data interface{}

	switch inFormat {
	case "y":
		var slice yaml.MapSlice
		err = yaml.Unmarshal(inputBytes, &slice)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing YAML: %v\n", err)
			os.Exit(1)
		}
		data = slice
	case "j":
		dec := json.NewDecoder(bytes.NewReader(inputBytes))
		dec.UseNumber()
		data, err = decodeJSON(dec)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing JSON: %v\n", err)
			os.Exit(1)
		}
	case "t":
		var m map[string]interface{}
		_, err = toml.Decode(string(inputBytes), &m)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing TOML: %v\n", err)
			os.Exit(1)
		}
		data = m
	case "c":
		astFile, err := hcl.ParseBytes(inputBytes)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing HCL: %v\n", err)
			os.Exit(1)
		}
		data = astToSlice(astFile)
	}

	data = parseFloats(data, keepFloats)
	data = sanitizeFloats(data, keepFloats)

	switch outFormat {
	case "y":
		if !parseKeys {
			// standard string keys logic, handled by default
		}
		b, err := yaml.Marshal(data)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error writing YAML: %v\n", err)
			os.Exit(1)
		}
		fmt.Print(string(b))
	case "j":
		b, err := encodeJSON(data, escapeHTML, indent)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error writing JSON: %v\n", err)
			os.Exit(1)
		}
		fmt.Println(string(b))
	case "t":
		var buf bytes.Buffer
		enc := toml.NewEncoder(&buf)
		if indent {
			enc.Indent = "  "
		}
		// TOML doesn't handle MapSlice well. Convert to map.
		m := sliceToMap(data)
		err = enc.Encode(m)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error writing TOML: %v\n", err)
			os.Exit(1)
		}
		fmt.Print(buf.String())
	case "c":
		b, err := encodeJSON(data, false, false)
		if err == nil {
			astFile, err := hcl.ParseBytes(b)
			if err == nil {
				var buf bytes.Buffer
				printer.Fprint(&buf, astFile)
				fmt.Println(buf.String())
				return
			}
		}
		fmt.Fprintf(os.Stderr, "Error writing HCL\n")
		os.Exit(1)
	}
}

func sliceToMap(v interface{}) interface{} {
	switch val := v.(type) {
	case yaml.MapSlice:
		m := make(map[string]interface{})
		for _, item := range val {
			m[fmt.Sprintf("%v", item.Key)] = sliceToMap(item.Value)
		}
		return m
	case []interface{}:
		var a []interface{}
		for _, item := range val {
			a = append(a, sliceToMap(item))
		}
		return a
	}
	return v
}
